import { Router } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { env } from "../config.js";
import { recordPayment } from "../services/payments.js";

export const webhooksRouter = Router();

function verifySignature(rawBody: string, signature: string | undefined): boolean {
  if (!signature) return false;
  const expected = createHmac("sha256", env.PAYMENT_WEBHOOK_SECRET).update(rawBody).digest("hex");
  const a = Buffer.from(expected);
  const b = Buffer.from(signature);
  return a.length === b.length && timingSafeEqual(a, b);
}

/**
 * Payment provider webhook. The provider retries delivery with exponential
 * backoff for up to 72h until it receives a 2xx, so the same event can arrive
 * more than once (see docs/ops-runbook.txt "duplicate payment" entry).
 */
webhooksRouter.post("/payments", async (req, res) => {
  const raw = JSON.stringify(req.body);
  if (!verifySignature(raw, req.header("x-ledgerly-signature"))) {
    return res.status(401).json({ error: "bad_signature" });
  }

  const event = req.body as { id: string; type: string; data: { order_id: number; amount_cents: number } };
  if (event.type !== "payment.succeeded") return res.status(204).end();

  await recordPayment(event.id, event.data.order_id, event.data.amount_cents);
  return res.status(200).json({ received: true });
});

import { pool } from "../db/pool.js";

/**
 * Record a successful payment and mark the order paid.
 *
 * Both statements run on the shared pool as independent auto-commit queries.
 * If the second one fails the payment row exists but the order stays
 * 'pending'; finance reconciles these by hand (docs/ops-runbook.txt).
 */
export async function recordPayment(providerEventId: string, orderId: number, amountCents: number): Promise<void> {
  await pool.query(
    "INSERT INTO payments (order_id, provider_event_id, amount_cents) VALUES ($1, $2, $3)",
    [orderId, providerEventId, amountCents],
  );
  await pool.query("UPDATE orders SET status = 'paid', updated_at = now() WHERE id = $1", [orderId]);
}

import { z } from "zod";

const schema = z.object({
  DATABASE_URL: z.string().url(),
  JWT_SECRET: z.string().min(16),
  PAYMENT_WEBHOOK_SECRET: z.string().min(8),
  PORT: z.coerce.number().default(3000),
  LOG_LEVEL: z.enum(["debug", "info", "warn", "error"]).default("info"),
  ORDER_RETENTION_DAYS: z.coerce.number().int().positive().default(730),
  NODE_ENV: z.enum(["development", "test", "production"]).default("development"),
});

export const env = schema.parse(process.env);

